<script setup>defineOptions({inheritAttrs:false});defineProps({id:{type:String,required:true},modelValue:{type:String,default:''},describedby:{type:String,default:undefined},invalid:Boolean,disabled:Boolean,readonly:Boolean});defineEmits(['update:modelValue'])</script>
